select id,country_name,international_dialing_code,delete_type,country_initial,country_common_use from ${database.prefix.userms}hou_base_country where 1 = 1
and country_name LIKE CONCAT('%',#{param.countryName},'%')
and country_common_use = #{param.countryCommonUse}

select count(1)
from ${database.prefix.userms}hou_base_country
where (country_name = '中国' or delete_type = 1) and id = #{countryId}
